import numpy as np, torch, model
net=model.load(); rows=[3,4,7]
torch.manual_seed(1); N=8192
xs=torch.randn(N,2); cs=torch.rand(N); cn=cs.numpy()
W=torch.tensor(np.load('probeW.npy')); b=torch.tensor(np.load('probeb.npy'))
def run(delta=None,K=(0,0)):
    x=xs.clone(); fires=np.zeros(N,bool)
    for k in range(20):
        t=torch.full((N,),1-k/20)
        v,a=net.velocity(x,t,cs,("blocks.2.act",),count=False)
        if delta is not None and K[0]<=k<K[1]:
            f=(a["blocks.2.act"]@W+b>0); fires|=f.numpy()
            v=v+f.float()[:,None]*torch.tensor(delta,dtype=torch.float32)
        x=x-v/20
    return x.numpy(),fires
def inbasin(x):
    m=np.zeros(len(x),bool)
    for j in rows: m|=model.in_basin(j,x)
    return m
with torch.no_grad(): a0,_=run()
y=inbasin(a0)&(cn>0.6); idx=np.where(y)[0]; print('target',y.sum())
ref=a0[~y]; rc=cn[~y]
def typical(x,c):
    D=np.linalg.norm(x[:,None]-ref[None],axis=2)+100*(np.abs(c[:,None]-rc[None])>0.03)
    return D.min(1)
res=[]
with torch.no_grad():
  for K in [(12,16)]:
    for mag in [10,20,40]:
      for ang in range(0,360,45):
        dl=[-mag*np.cos(np.radians(ang)),-mag*np.sin(np.radians(ang))]
        a1,f=run(dl,K)
        tb=inbasin(a1)[y].mean(); drift=((np.linalg.norm(a1-a0,axis=1)>0.3)&~y).mean()
        typ=np.median(typical(a1[idx],cn[idx]))
        res.append((mag,ang,round(tb,3),round(drift,4),round(typ,3),round(f[~y].mean(),4)))
for r in sorted(res,key=lambda r:(r[2]+r[3]*20+r[4])): print(r)
